	\caption{\textsc{Foremost Forest}}
	\Input{Simple temporal graph $\mathcal{G}=(V, E, \lambda)$; set of nodes $S\subseteq V$.}
	\Output{Foremost forest for $S$.}
	\smallskip
	$k = |S| - 1$,
	$\mathcal{G}^{k}_F=(S, \emptyset, \emptyset)$\;
	\While{$\mathrm{ext}(\mathcal{G}^k_F)\neq \emptyset$}{
		$k := k + 1$\;
		$e_k := arg\,min \{ \lambda(e) \mid e \in \mathrm{ext}(\mathcal{G}^{k-1}_F)\}$\;
		$\mathcal{G}^k_F := \mathcal{G}^{k-1}_F \cup e_k$\;
	}
  \Return{$\mathcal{G}^k_F$}
  \label{alg: foremost forest}

